from taf.gnb.oam.coam.cu.exception import (
    APINotImplemented
)
from taf.gnb.oam.coam.cu.services.internal.cp_config.http_client import (
    CPCONFIGv1HttpClient,
)
from taf.gnb.oam.coam.cu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.cu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.cu.services.internal.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.cu.services.licensed.sec.sec_licensed_v1 import SECLicensedv1
from taf.gnb.oam.coam.cu.utilities.poll_status import poll_status


@auto_token_refresh()
class CPCONFIGv1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        self.local_client = CPCONFIGv1HttpClient(base_url=con_details.base_url,
                                                 connection_alias=con_details.alias)

    def reset_cu(self, timeout=30):
        return self.local_client.reset_cu(timeout=timeout)

    def start_uplane_trace_stream(self, trace_type, target_component, timeout=30):
        raise APINotImplemented("Uplane tracing has been moved from CP-CONFIG to ASM."
                                "Please connect_to CU with a version higher than or equal to cuoam_24r2")

    def get_active_trace_streams(self, timeout=30):
        raise APINotImplemented("Uplane tracing has been moved from CP-CONFIG to ASM."
                                "Please connect_to CU with a version higher than or equal to cuoam_24r2")

    def stop_uplane_trace_stream(self, trace_id, timeout=30):
        raise APINotImplemented("Uplane tracing has been moved from CP-CONFIG to ASM."
                                "Please connect_to CU with a version higher than or equal to cuoam_24r2")

    def get_traces_activation_status(self, timeout=30):
        raise APINotImplemented("Uplane tracing has been moved from CP-CONFIG to ASM."
                                "Please connect_to CU with a version higher than or equal to cuoam_24r2")

    def remove_uplane_trace_stream(self, trace_id, timeout=30):
        raise APINotImplemented("Uplane tracing has been moved from CP-CONFIG to ASM."
                                "Please connect_to CU with a version higher than or equal to cuoam_24r2")

    def reset_cells(self, dist_name, timeout=30):
        operation_id = self.local_client.trigger_cell_reset(dist_name=dist_name, timeout=timeout)["id"]

        return poll_status(
            instance=self.local_client,
            method_name="get_cell_reset_operation_status",
            operation_id=operation_id,
            teardown_method_name="delete_cell_reset_operation",
            timeout=timeout
        )["status"]
